#!/bin/bash
set -eo pipefail
umask 077
/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -B - <<'PY_XML_DEPLOY'
import base64,hashlib,io,json,os,pathlib,shutil,subprocess,sys,zipfile
root=pathlib.Path('/data1/home/sunyiq/china_input_completion_hpc_20261015_001/missing_vegetation_xml_v1')
assert root.parent.resolve(strict=True)==root.parent and not root.exists() and not root.is_symlink()
assert (root.parent/'terrain_unit_provenance_v1/OWN_RECOVERY_JOB_ID').read_text().strip()=='243151'
assert shutil.disk_usage(root.parent).free>=256*1024**2
packed=base64.b64decode('',validate=True)
assert len(packed)==26937 and hashlib.sha256(packed).hexdigest()=='b0b33d98662a3429135aed814fd669f07e2ab072bafbcc4957b218c1e70289b2'
table=json.loads('{"recover_missing_xml_v3.py":{"bytes":15748,"sha256":"34e2ff1f492b18ec822809a856122b3ff88545c289815e0a7b852887a0270ced"},"missing_xml_transport_v1.py":{"bytes":2736,"sha256":"f19878d942e196582571492e073dc48323022755cda9f4fe0c118f0f3a418e89"},"catalog_semantics.py":{"bytes":1904,"sha256":"98db5e719d32f41ec36bbca4c2864b095c811f820fb88b9df24baee24ef9031c"},"MISSING_XML_CONTRACT.json":{"bytes":337428,"sha256":"68f4c65b8f251c2b26a30a299349498d4b78220ec09e6cf833c20ed450ecb3e2"},"missing_xml_control_v1.py":{"bytes":5895,"sha256":"f5d92510ac4b04497fb55598a4c384100800e5af3eef692bdb4a44b2bc28f5ab"},"ENTRY_TABLE.json":{"bytes":693,"sha256":"ebd0108906289a7af0f2687d9f94eab65ee70b5f0795cea2b0e7e597de728ae5"}}')
with zipfile.ZipFile(io.BytesIO(packed)) as archive:
 assert len(archive.namelist())==6 and archive.namelist()==sorted(table)
 assert sum(x.file_size for x in archive.infolist())<=1048576
 values={}
 for name in archive.namelist():
  assert pathlib.PurePosixPath(name).name==name and not name.startswith('.')
  raw=archive.read(name)
  assert len(raw)==table[name]['bytes'] and hashlib.sha256(raw).hexdigest()==table[name]['sha256']
  values[name]=raw
root.mkdir(mode=0o700)
for name in ('requests','documents'): (root/name).mkdir(mode=0o700)
for name,raw in values.items():
 with (root/name).open('xb') as stream:stream.write(raw)
with (root/'LAUNCH_REQUESTED.json').open('x') as stream:
 json.dump(dict(one_launch_only=True,automatic_retries=0,scientific_array_reads=0,new_slurm_jobs=0),stream)
env=dict(os.environ,CUDA_VISIBLE_DEVICES='',PYTHONDONTWRITEBYTECODE='1',PYTHONPATH='',
 OMP_NUM_THREADS='1',OPENBLAS_NUM_THREADS='1',MKL_NUM_THREADS='1',NUMEXPR_NUM_THREADS='1')
argv=[sys.executable,'-B',str(root/'missing_xml_control_v1.py')]
with (root/'control.stdout').open('xb') as out,(root/'control.stderr').open('xb') as err:
 process=subprocess.Popen(argv,cwd=root,env=env,stdin=subprocess.DEVNULL,stdout=out,stderr=err,start_new_session=True)
 ticks=None
 try:
  stat=pathlib.Path('/proc')/str(process.pid)/'stat'
  value=stat.read_text();ticks=value[value.rfind(')')+2:].split()[19]
 except FileNotFoundError:pass
 launch=dict(pid=process.pid,argv=argv,start_ticks=ticks,remote_root=str(root),
  hard_child_seconds=1860,acceptance_seconds=1800,automatic_retries=0,new_slurm_jobs=0)
 with (root/'LAUNCH.json').open('x') as stream:json.dump(launch,stream,indent=2)
print('OWN_MISSING_XML_PAYLOAD_VERIFIED=6')
print('OWN_MISSING_XML_HELPER_PID='+str(process.pid))
print('OWN_MISSING_XML_LAUNCH_DONE')
PY_XML_DEPLOY
